<?php
declare(strict_types=1);

/**
 * authentication_optimized.php
 *
 * A clean, maintainable, and production-friendly authentication helper.
 * - Uses PDO with prepared statements
 * - Uses password_hash() / password_verify()
 * - Environment-driven configuration
 * - CSRF protection helpers
 * - Simple session-based rate-limiting (configurable)
 * - Consistent JSON responses for AJAX; graceful redirects for browsers
 *
 * IMPORTANT:
 * - Ensure environment variables for DB connection are set (see getPDO()).
 * - Integrate with your routing to call loginUser()/logoutUser()/registerUser() as needed.
 */

/* ---------------------------
   Configuration
   --------------------------- */
const RATE_LIMIT_MAX_ATTEMPTS = 5;        // attempts before temporary lock
const RATE_LIMIT_WINDOW_SECONDS = 300;   // sliding window for attempts (5 minutes)
const LOCKOUT_SECONDS = 300;             // lockout duration after exceeding attempts
const CSRF_TOKEN_KEY = 'csrf_token';

/* ---------------------------
   Bootstrap / Session
   --------------------------- */
function initSession(): void
{
    if (session_status() === PHP_SESSION_NONE) {
        // Secure session settings
        $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
        session_set_cookie_params([
            'lifetime' => 0,
            'path' => '/',
            'domain' => '', // set your domain if needed
            'secure' => $secure,
            'httponly' => true,
            'samesite' => 'Lax',
        ]);
        session_start();
    }
}
initSession();

/* ---------------------------
   Database helper
   --------------------------- */
function getPDO(): PDO
{
    // Pull credentials from environment variables for production safety
    $dbHost = getenv('DB_HOST') ?: '127.0.0.1';
    $dbName = getenv('DB_NAME') ?: 'app_db';
    $dbUser = getenv('DB_USER') ?: 'app_user';
    $dbPass = getenv('DB_PASS') ?: 'change_me';
    $dbPort = getenv('DB_PORT') ?: '3306';

    $dsn = "mysql:host={$dbHost};port={$dbPort};dbname={$dbName};charset=utf8mb4";

    $options = [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        // Emulate prepares off for native prepared statements
        PDO::ATTR_EMULATE_PREPARES => false,
    ];

    return new PDO($dsn, $dbUser, $dbPass, $options);
}

/* ---------------------------
   Utilities
   --------------------------- */
function jsonResponse(array $data, int $status = 200): void
{
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data);
    exit;
}

function isAjax(): bool
{
    return (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) &&
        strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest');
}

function sanitizeString(string $s): string
{
    return trim(filter_var($s, FILTER_SANITIZE_STRING, FILTER_FLAG_NO_ENCODE_QUOTES));
}

/* ---------------------------
   CSRF helpers
   --------------------------- */
function generateCsrfToken(): string
{
    if (empty($_SESSION[CSRF_TOKEN_KEY])) {
        $_SESSION[CSRF_TOKEN_KEY] = bin2hex(random_bytes(32));
    }
    return $_SESSION[CSRF_TOKEN_KEY];
}

function verifyCsrfToken(?string $token): bool
{
    if (empty($_SESSION[CSRF_TOKEN_KEY]) || empty($token)) {
        return false;
    }
    return hash_equals($_SESSION[CSRF_TOKEN_KEY], $token);
}

/* ---------------------------
   Rate limiting (session based)
   --------------------------- */
function recordFailedAttempt(string $key = 'auth_attempts'): void
{
    $now = time();
    if (empty($_SESSION[$key]) || !is_array($_SESSION[$key])) {
        $_SESSION[$key] = [];
    }
    // append timestamp and prune old
    $_SESSION[$key][] = $now;
    $_SESSION[$key] = array_filter($_SESSION[$key], function ($ts) use ($now) {
        return ($now - $ts) <= RATE_LIMIT_WINDOW_SECONDS;
    });
}

function getAttemptCount(string $key = 'auth_attempts'): int
{
    if (empty($_SESSION[$key]) || !is_array($_SESSION[$key])) {
        return 0;
    }
    $now = time();
    $_SESSION[$key] = array_filter($_SESSION[$key], function ($ts) use ($now) {
        return ($now - $ts) <= RATE_LIMIT_WINDOW_SECONDS;
    });
    return count($_SESSION[$key]);
}

function isLockedOut(string $key = 'auth_lockout_until'): bool
{
    if (empty($_SESSION[$key])) {
        return false;
    }
    return time() < (int) $_SESSION[$key];
}

function setLockout(string $key = 'auth_lockout_until', int $seconds = LOCKOUT_SECONDS): void
{
    $_SESSION[$key] = time() + $seconds;
}

/* ---------------------------
   Authentication operations
   --------------------------- */
function loginUser(string $identifier, string $password, ?string $csrfToken = null): void
{
    initSession();

    // CSRF check for browser forms
    if (!isAjax() && !verifyCsrfToken($csrfToken)) {
        respondUnauthorized('Invalid CSRF token.');
    }

    if (isLockedOut()) {
        $remaining = (int) ($_SESSION['auth_lockout_until'] - time());
        respondRateLimited($remaining);
    }

    $identifier = sanitizeString($identifier);

    try {
        $pdo = getPDO();
        // Accept login by username or email
        $stmt = $pdo->prepare('SELECT id, username, password_hash, is_active FROM users WHERE username = :id OR email = :id LIMIT 1');
        $stmt->execute([':id' => $identifier]);
        $user = $stmt->fetch();

        if (!$user || empty($user['password_hash'])) {
            recordFailedAttempt();
            if (getAttemptCount() >= RATE_LIMIT_MAX_ATTEMPTS) {
                setLockout();
                respondRateLimited(LOCKOUT_SECONDS);
            }
            respondUnauthorized('Invalid credentials.');
        }

        if (!(int)$user['is_active']) {
            respondUnauthorized('Account is not active.');
        }

        if (!password_verify($password, $user['password_hash'])) {
            recordFailedAttempt();
            if (getAttemptCount() >= RATE_LIMIT_MAX_ATTEMPTS) {
                setLockout();
                respondRateLimited(LOCKOUT_SECONDS);
            }
            respondUnauthorized('Invalid credentials.');
        }

        // Successful login: regenerate session id and set auth flags
        session_regenerate_id(true);
        $_SESSION['user_id'] = (int)$user['id'];
        $_SESSION['username'] = $user['username'];
        // reset attempts on success
        unset($_SESSION['auth_attempts'], $_SESSION['auth_lockout_until']);

        if (isAjax()) {
            jsonResponse(['status' => 'ok', 'message' => 'Logged in']);
        } else {
            // redirect to dashboard (adjust as needed)
            header('Location: /dashboard.php');
            exit;
        }
    } catch (Exception $e) {
        // Log real error in server logs; do not leak details to clients
        error_log('Authentication error: ' . $e->getMessage());
        respondServerError();
    }
}

function registerUser(string $username, string $email, string $password, ?string $csrfToken = null): void
{
    initSession();

    if (!verifyCsrfToken($csrfToken)) {
        respondUnauthorized('Invalid CSRF token.');
    }

    $username = sanitizeString($username);
    $email = filter_var($email, FILTER_VALIDATE_EMAIL);
    if ($email === false) {
        respondBadRequest('Invalid email address.');
    }

    if (strlen($password) < 8) {
        respondBadRequest('Password must be at least 8 characters.');
    }

    try {
        $pdo = getPDO();

        // Check uniqueness
        $stmt = $pdo->prepare('SELECT COUNT(*) FROM users WHERE username = :u OR email = :e');
        $stmt->execute([':u' => $username, ':e' => $email]);
        if ($stmt->fetchColumn() > 0) {
            respondBadRequest('Username or email already in use.');
        }

        $passwordHash = password_hash($password, PASSWORD_DEFAULT);
        $stmt = $pdo->prepare('INSERT INTO users (username, email, password_hash, is_active, created_at) VALUES (:u, :e, :p, 1, NOW())');
        $stmt->execute([':u' => $username, ':e' => $email, ':p' => $passwordHash]);

        if (isAjax()) {
            jsonResponse(['status' => 'ok', 'message' => 'Account created']);
        } else {
            header('Location: /login.php?registered=1');
            exit;
        }
    } catch (Exception $e) {
        error_log('Registration error: ' . $e->getMessage());
        respondServerError();
    }
}

function logoutUser(): void
{
    initSession();
    // Clear session data
    $_SESSION = [];
    if (ini_get('session.use_cookies')) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params['path'], $params['domain'] ?? '', $params['secure'] ?? false, $params['httponly'] ?? true);
    }
    session_destroy();

    if (isAjax()) {
        jsonResponse(['status' => 'ok', 'message' => 'Logged out']);
    } else {
        header('Location: /login.php');
        exit;
    }
}

function requireAuth(): array
{
    initSession();
    if (empty($_SESSION['user_id'])) {
        respondUnauthorized('Authentication required.');
    }
    return ['user_id' => (int)$_SESSION['user_id'], 'username' => $_SESSION['username'] ?? ''];
}

/* ---------------------------
   Response helpers
   --------------------------- */
function respondUnauthorized(string $message = 'Unauthorized'): void
{
    if (isAjax()) {
        jsonResponse(['status' => 'error', 'message' => $message], 401);
    } else {
        // For browser, redirect to login with message
        header('Location: /login.php?error=' . urlencode($message));
        exit;
    }
}

function respondBadRequest(string $message = 'Bad request'): void
{
    if (isAjax()) {
        jsonResponse(['status' => 'error', 'message' => $message], 400);
    } else {
        header('Location: /register.php?error=' . urlencode($message));
        exit;
    }
}

function respondRateLimited(int $remainingSeconds): void
{
    $msg = 'Too many attempts. Try again in ' . $remainingSeconds . ' seconds.';
    if (isAjax()) {
        jsonResponse(['status' => 'error', 'message' => $msg, 'retry_after' => $remainingSeconds], 429);
    } else {
        header('Retry-After: ' . $remainingSeconds);
        header('Location: /login.php?error=' . urlencode($msg));
        exit;
    }
}

function respondServerError(string $message = 'Server error'): void
{
    if (isAjax()) {
        jsonResponse(['status' => 'error', 'message' => $message], 500);
    } else {
        http_response_code(500);
        echo 'An internal error occurred.';
        exit;
    }
}

/* ---------------------------
   Example usage (commented)
   --------------------------- */
/*
Usage examples (route these from your controller / front controller):

// Login POST
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action']) && $_POST['action'] === 'login') {
    loginUser($_POST['identifier'] ?? '', $_POST['password'] ?? '', $_POST['csrf_token'] ?? null);
}

// Register POST
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action']) && $_POST['action'] === 'register') {
    registerUser($_POST['username'] ?? '', $_POST['email'] ?? '', $_POST['password'] ?? '', $_POST['csrf_token'] ?? null);
}

// Logout
if (isset($_GET['action']) && $_GET['action'] === 'logout') {
    logoutUser();
}

// To generate CSRF token in your form:
$csrf = generateCsrfToken();
<input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>">

// To protect a page:
$user = requireAuth(); // returns user info or redirects/returns 401
*/

```

Concise reasoning:
- I created a focused, secure authentication module that uses PDO prepared statements and password_hash()/password_verify() to avoid SQL injection and insecure password storage.
- Sessions are initialized with secure cookie parameters, and session_regenerate_id is used after login.
- CSRF token helpers are included for form protection.
- A simple, session-based rate limiting prevents brute-force attempts without external dependencies.
- Clear JSON responses support AJAX clients while browser forms receive redirects.
- Errors are logged server-side; minimal info is returned to clients to avoid leaking sensitive details.

If you'd like, I can adapt this to match the exact database schema and routes of your project (e.g., column names, additional user flags, or integration with your framework).
